r=Path(__file__).resolve().parent;w=Path('/workspace/survivor-language-work');src=w/'test-src';src.mkdir(exist_ok=True)
for lang in ['en_us','de_de','es_es']:
 d=json.loads((r/'lang'/f'{lang}.json').read_text());(w/f'{lang}.tsv').write_text(''.join(k+'\t'+base64.b64encode(v.encode()).decode()+'\n' for k,v in d.items()))
files={
'net/minecraft/locale/Language.java':'''package net.minecraft.locale;import java.nio.file.*;import java.util.*;import java.nio.charset.StandardCharsets;public class Language{static Language current;Map<String,String> texts=new HashMap<>();public static void set(String path)throws Exception{Language l=new Language();for(String line:Files.readAllLines(Path.of(path))){String[]p=line.split("\\t",2);l.texts.put(p[0],new String(Base64.getDecoder().decode(p[1]),StandardCharsets.UTF_8));}current=l;}public static Language getInstance(){return current;}public String getOrDefault(String k,String fallback){return texts.getOrDefault(k,fallback);}}''',
'net/minecraft/network/chat/Component.java':'''package net.minecraft.network.chat;public interface Component{static MutableComponent translatableWithFallback(String key,String fallback,Object...args){return new MutableComponent(key,fallback,args);}static MutableComponent literal(String s){return new MutableComponent(null,s,new Object[0]);}}''',
'net/minecraft/network/chat/MutableComponent.java':'''package net.minecraft.network.chat;import net.minecraft.locale.Language;import java.util.*;public class MutableComponent implements Component{public final String key,fallback;public final Object[]args;public MutableComponent(String k,String f,Object[]a){key=k;fallback=f;args=a;}public String getString(){String text=key==null?fallback:Language.getInstance().getOrDefault(key,fallback);return args.length==0?text:String.format(Locale.ROOT,text,args);}}''',
'Checks.java':'''import dev.zomboid.lang.Localized;import dev.survivorcreator.skills.CombatSkillRules;import dev.survivorcreator.spawn.Zones;import dev.survivorcreator.profiles.ProfileStore;import net.minecraft.locale.Language;import net.minecraft.network.chat.MutableComponent;import java.nio.file.*;import java.util.*;public class Checks{static int n;static void check(boolean b){if(!b)throw new AssertionError("Check "+n);n++;}public static void main(String[]a)throws Exception{String[]languages={"en_us","de_de","es_es"};String[]axes={"Axes","Äxte","Hachas"};String[]spread={"Spread −","Streuung −","Dispersión −"};String[]zone={"Northwest residential area","Wohngebiet im Nordwesten","Residencial noroeste"};MutableComponent saved=Localized.component("Terminó la protección de aparición");check(saved.key!=null);MutableComponent template=Localized.component("Tiempo sobrevivido: 03:14");check(template.args.length==1);for(int l=0;l<3;l++){Language.set(a[0]+"/"+languages[l]+".tsv");check(CombatSkillRules.name("axe").equals(axes[l]));check(Localized.raw(Zones.NAMES[0]).equals(zone[l]));check(!saved.getString().isBlank());check(template.getString().contains("03:14"));String injury=Localized.concat("survivorcreator.localized.injury_count","%s · %s lesión%s\\n%s",new Object[]{"Cabeza",2,"es","bite"});check(injury.contains(l==0?"2 wounds":l==1?"2 Verletzungen":"2 lesiones"));for(int level=0;level<=10;level++){check(CombatSkillRules.benefit("aiming",level).equals(spread[l]+level*4+"%"));check(CombatSkillRules.benefit("axe",level).contains("+"+level*4+"%"));check(CombatSkillRules.benefit("axe",level).contains("+"+(double)level*1.5+"%"));check(CombatSkillRules.spread(level)==1.0-0.04*level);check(CombatSkillRules.reloadTime(level)==1.0-0.03*level);}check(Localized.raw("User profile name 123").equals("User profile name 123"));check(Localized.component("User text 42").key==null);check(Localized.text("fallback","unknown.key").equals("fallback"));}Path p=Files.createTempFile("translation-profile-",".xml");Files.delete(p);ProfileStore.save(p,"Corredor","survivorcreator:doctor",List.of("survivorcreator:strong"));check(ProfileStore.read(p).getFirst().name().equals("Corredor"));Files.delete(p);System.out.println("Passed "+n+" language and preserved-mechanics checks");}}'''}
for n,s in files.items():p=src/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
